def unesc(s):
    return s.replace("&amp;","&").replace("&apos;","'").replace("&quot;",'"').replace("&lt;","<").replace("&gt;",">")
def esc(s):
    return s.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;")
def norm(s):
    return re.sub(r"\s+"," ",s).strip()

# Load allowlist for identical-to-EN detection
allow_set = set()
if os.path.exists("en_keep_allowlist.txt"):
    with open("en_keep_allowlist.txt", encoding="utf-8") as f:
        for line in f:
            line = line.strip()
            if line and not line.startswith("#"):
                allow_set.add(line)

Tnorm = {norm(k): v for k, v in T.items()}

msg_re = re.compile(r"<message>.*?</message>", re.S)
src_re = re.compile(r"<source>(.*?)</source>", re.S)
tr_unf_re = re.compile(r'<translation type="unfinished"\s*(/>|>\s*</translation>)', re.S)
tr_ident_re = re.compile(r"<translation>(.*?)</translation>", re.S)

total_filled = {}
total_remaining_unf = {}
total_remaining_ident = {}

for i, lang in enumerate(LANGS):
    fn = f"fceux11_{lang}.ts"
    xml = open(fn, encoding="utf-8").read()
    filled = 0
    def repl(m):
        global filled
        block = m.group(0)
        sm = src_re.search(block)
        if not sm:
            return block
        key = norm(unesc(sm.group(1)))
        tr = Tnorm.get(key)
        if tr is None or len(tr) <= i:
            return block
        new_val = esc(tr[i])

        # Handle unfinished entries - always fill if we have a translation
        if 'type="unfinished"' in block:
            filled += 1
            return tr_unf_re.sub(lambda _: "<translation>" + new_val + "</translation>", block, count=1)

        # Handle identical-to-EN entries (not in allowlist)
        tr_match = tr_ident_re.search(block)
        if tr_match:
            old_tr = norm(unesc(tr_match.group(1)))
            if old_tr == key and key not in allow_set:
                filled += 1
                return tr_ident_re.sub(lambda _: "<translation>" + new_val + "</translation>", block, count=1)

        return block

    xml2 = msg_re.sub(repl, xml)

    # Count remaining issues
    remaining_unf = xml2.count('type="unfinished"')
    remaining_ident = 0
    for m in re.finditer(r"<message>.*?</message>", xml2, re.S):
        sm = src_re.search(m.group(0))
        tm = tr_ident_re.search(m.group(0))
        if sm and tm:
            s = norm(unesc(sm.group(1)))
            t = norm(unesc(tm.group(1)))
            if s == t and s not in allow_set:
                remaining_ident += 1

    if xml2 != xml:
        open(fn, "w", encoding="utf-8", newline="").write(xml2)

    total_filled[lang] = filled
    total_remaining_unf[lang] = remaining_unf
    total_remaining_ident[lang] = remaining_ident
    print(f"{lang}: filled={filled} remaining_unfinished={remaining_unf} remaining_identical_not_in_allowlist={remaining_ident}")

# Report unused dict keys
xml = open("fceux11_zh_CN.ts", encoding="utf-8").read()
used = set()
for m in msg_re.finditer(xml):
    sm = src_re.search(m.group(0))
    if sm:
        used.add(norm(unesc(sm.group(1))))
unused = [k for k in Tnorm if k not in used]
if unused:
    print(f"\nUNUSED_DICT_KEYS ({len(unused)}):")
    for k in unused[:20]:
        print(f"  {k}")
    if len(unused) > 20:
        print(f"  ... and {len(unused)-20} more")
else:
    print("\nUNUSED_DICT_KEYS: none")

# Summary
print(f"\n=== SUMMARY ===")
all_zero = True
for lang in LANGS:
    ok = total_remaining_unf[lang] == 0 and total_remaining_ident[lang] == 0
    if not ok: all_zero = False
    status = "DONE" if ok else "INCOMPLETE"
    print(f"  {lang}: filled={total_filled[lang]} {status}")
if all_zero:
    print("\nAll languages fully translated!")
else:
    print("\nSome languages have remaining issues. Check output above.")
